#include <vector>
#include <CGAL/Exact_predicates_inexact_constructions_kernel.h>

typedef CGAL::Exact_predicates_inexact_constructions_kernel Kernel;
typedef Kernel::Point_2 Point_2;
typedef Kernel::FT FT;

FT polygon_area(const std::vector<Point_2>& polygon) {
    FT result = FT(0);
    if (polygon.size() < 3) return result;

    for (size_t i = 1; i < polygon.size() - 1; ++i) {
        result = result + CGAL::area(polygon[0], polygon[i], polygon[i+1]);
    }
    return result;
}

int main() {
    std::vector<Point_2> poly = {Point_2(0,0), Point_2(1,0), Point_2(1,1), Point_2(0,1)};
    FT area = polygon_area(poly);
    return 0;
}

